let v = msg.payload;

// Convert JSON text to an object
if (typeof v === "string") {
    try {
        v = JSON.parse(v);
    } catch (e) {
        node.warn("Invalid sensor JSON");
        return null;
    }
}

if (!v || typeof v !== "object") {
    node.warn("Expected a sensor data object");
    return null;
}

// Read the exact field names sent by your sensor
const t = Number(v.temperature_c ?? NaN);
const h = Number(v.humidity_percent ?? NaN);
const p = Number(v.pressure_hpa ?? NaN);

// Stop if any reading is missing or invalid
if (![t, h, p].every(Number.isFinite)) {
    node.warn("Missing or invalid temperature, humidity or pressure");
    return null;
}

// Save actual sensor readings for the decision node
// Pressure is already in hPa
flow.set("indoor", {
    t: t,
    h: h,
    p: p
});

// Tell the next node this is a new indoor reading
msg.src = "in";

return msg;

const d = msg.payload;
if (!d || !d.main) { node.warn('Weather API problem: ' + JSON.stringify(d)); return null; }
flow.set('outdoor', {
    t: d.main.temp, h: d.main.humidity, p: d.main.pressure, feels: d.main.feels_like,
    wind: d.wind ? d.wind.speed : 0,
    main: d.weather[0].main, desc: d.weather[0].description, city: d.name
});
msg.src = 'out';
return msg;

const indoor = flow.get('indoor');
const outdoor = flow.get('outdoor');
const r1 = x => Math.round(x * 10) / 10;
const dew = (T, H) => { const a = 17.62, b = 243.12; const g = Math.log(Math.max(H, 1) / 100) + a * T / (b + T); return b * g / (a - g); };
const feels = (T, H, ws) => { const e = H / 100 * 6.105 * Math.exp(17.27 * T / (237.7 + T)); return T + 0.33 * e - 0.70 * ws - 4.0; };

// history for trends / sparkline (only when a new room reading arrives)
let hist = flow.get('hist') || [];
if (msg.src === 'in' && indoor && outdoor) {
    hist.push({ti: indoor.t, to: outdoor.t, p: indoor.p});
    if (hist.length > 40) hist.shift();
    flow.set('hist', hist);
}

const p = {ready: !!(indoor && outdoor), city: outdoor ? outdoor.city : '--',
           updated: new Date().toLocaleTimeString('en-IN')};
if (indoor) {
    p.inT = r1(indoor.t); p.inH = Math.round(indoor.h); p.inP = Math.round(indoor.p);
    p.inDew = r1(dew(indoor.t, indoor.h)); p.inFeel = r1(feels(indoor.t, indoor.h, 0.1));
}
if (outdoor) {
    p.outT = r1(outdoor.t); p.outH = Math.round(outdoor.h); p.outP = Math.round(outdoor.p);
    p.outDew = r1(dew(outdoor.t, outdoor.h)); p.outFeel = r1(outdoor.feels);
    p.wind = r1(outdoor.wind); p.weather = outdoor.desc; p.main = outdoor.main;
}

// pressure trend from room sensor history
p.trend = 'steady'; p.trendArrow = '→';
if (hist.length >= 6) {
    const d = hist[hist.length - 1].p - hist[0].p;
    if (d > 1) { p.trend = 'rising'; p.trendArrow = '↗'; }
    else if (d < -1) { p.trend = 'falling'; p.trendArrow = '↘'; }
}

// sparkline points
if (hist.length >= 2) {
    const vals = hist.flatMap(h => [h.ti, h.to]);
    const mn = Math.min(...vals) - 1, mx = Math.max(...vals) + 1, W = 300, H = 90;
    const pts = k => hist.map((h, i) => (i / (hist.length - 1) * W).toFixed(1) + ',' + (H - (h[k] - mn) / (mx - mn) * H).toFixed(1)).join(' ');
    p.sparkIn = pts('ti'); p.sparkOut = pts('to'); p.sparkMin = r1(mn); p.sparkMax = r1(mx);
}

let s;
if (!p.ready) {
    s = {icon: '⏳', accent: '#7a7468', title: 'Waiting for data',
         headline: 'Need both the room sensor (MQTT) and the weather feed (OpenWeather).', actions: []};
    p.score = 0; p.scoreLabel = '--';
    p.mold = {label: '--', pct: 0}; p.laundry = '--'; p.deltaText = '--';
} else {
    const raining = /Rain|Drizzle|Thunderstorm/.test(p.main || '');
    const dT = r1(p.inT - p.outT);
    p.deltaText = Math.abs(dT) < 0.5 ? 'Same temperature inside and out'
        : (dT > 0 ? 'Outside is ' + dT + '°C cooler' : 'Outside is ' + Math.abs(dT) + '°C hotter');

    if (p.main === 'Thunderstorm' || (raining && p.trend === 'falling')) {
        s = {icon: '⛈️', accent: '#5b4b8a', title: 'Storm Watch',
             headline: 'Rain with falling pressure: weather is turning. Lock the room down.',
             actions: ['Close all windows and balcony doors now',
                       'Bring in laundry and outdoor plants',
                       'Unplug sensitive electronics if lightning starts']};
    } else if (raining || (p.inDew >= 21 && p.outDew >= p.inDew - 1)) {
        s = {icon: '💧', accent: '#2f6f9f', title: 'Seal & Dehumidify',
             headline: 'The air outside is as damp as inside (dew point ' + p.outDew + '°C). Opening up makes it worse.',
             actions: ['Keep windows shut',
                       'Run AC in DRY mode or a dehumidifier until RH drops below 60% (now ' + p.inH + '%)',
                       'Set AC to 25-26°C, going colder only wastes power']};
    } else if ((p.inFeel >= 26.5 || p.inH >= 65) && p.outT <= p.inT - 1.5 && p.outDew <= p.inDew - 1.5) {
        s = {icon: '🌬️', accent: '#1f9d8a', title: 'Flush the Room',
             headline: 'Outside air is cooler and drier than your room. Free cooling is available.',
             actions: ['Open two opposite windows for 15-20 minutes',
                       p.wind >= 2 ? 'Wind is ' + p.wind + ' m/s, cross-ventilation will work well' : 'Wind is weak (' + p.wind + ' m/s), add a fan to push air through',
                       'Switch the AC off while ventilating']};
    } else if (p.inFeel >= 28) {
        s = {icon: '🥵', accent: '#e0663a', title: 'Cool Down Mode',
             headline: 'Feels like ' + p.inFeel + '°C inside and outside cannot help. Active cooling needed.',
             actions: ['AC at 24-25°C with fan on auto',
                       'Close curtains on the sun-facing side',
                       'Keep doors and windows closed']};
    } else if (p.inT < 21) {
        s = {icon: '🧣', accent: '#c98a1b', title: 'Warm Up Gently',
             headline: 'Room is on the cool side at ' + p.inT + '°C.',
             actions: ['Keep windows closed to hold heat',
                       'Add a layer instead of heating the whole room',
                       'Ventilate for only 5 minutes around midday']};
    } else {
        s = {icon: '🌿', accent: '#4c9a2a', title: 'Natural Breathing',
             headline: 'Conditions are comfortable. No machines needed.',
             actions: ['Leave a window cracked for fresh air',
                       'AC / heater can stay off and save power',
                       'Re-check if outside humidity jumps above 80%']};
    }

    let score = 100 - Math.abs(p.inFeel - 24.5) * 4.5;
    if (p.inH > 60) score -= (p.inH - 60) * 0.8; else if (p.inH < 35) score -= (35 - p.inH) * 0.8;
    p.score = Math.max(0, Math.min(100, Math.round(score)));
    p.scoreLabel = p.score >= 80 ? 'Comfortable' : p.score >= 60 ? 'Tolerable' : p.score >= 40 ? 'Stuffy' : 'Uncomfortable';

    p.mold = {label: p.inH > 70 ? 'High' : p.inH >= 60 ? 'Moderate' : 'Low',
              pct: Math.max(5, Math.min(100, (p.inH - 40) * 2.5))};
    p.laundry = raining ? 'Dry clothes indoors (fan or AC)'
        : (p.outH < 70 && p.wind >= 1.5) ? 'Good drying day, hang laundry outside'
        : 'Outdoor drying will be slow';
}
Object.assign(p, {icon: s.icon, accent: s.accent, strategy: s.title, headline: s.headline, actions: s.actions});
msg.payload = p;
return msg;
